  });
  addLbl(itInput, RGB[i], inU + inDU[i] - 2.12 - 0.30, inV[i], F(17));
}
addLbl(itInput, 'W', inU + inDU[2] - 1.20, 0.28, F(17));
addLbl(itInput, 'H', inU + inDU[2] + 1.20, 0.28, F(17));

const itBr3 = newItem(0, 'neutral');
addBracket(itBr3, -3.90, 0.30, 2.62);
addLbl(itBr3, rot('3 channels'), -4.10, 1.46, F(14));

/* ---------- ARROW 1 ---------- */
const itArrow1 = newItem(1, 'neutral');
addArrow(itArrow1, -3.58, -2.22, 1.51);

/* ---------- LAYER 1 FEATURE MAPS ---------- */
const itTitleL1 = newItem(1, 'neutral');
addStroke(itTitleL1, [[[-2.15, 3.04], [0.62, 3.04]]], 0.05);
addLbl(itTitleL1, 'Layer 1 feature maps', -0.76, 3.36, F(19));

const l1U = -0.76;
const itL1 = [];
for (let i = 0; i < 5; i++) {
  const it = newItem(1, 'act'); itL1.push(it);
  const v = 1.57 + (2 - i) * 0.40, du = -0.07 * i;
  const g = addPlate(it, l1U + du, v, 1.5, PINK, PINKHI);
