      ' below: three 3×3 kernels, one per RGB input channel, summed together.'
  });
}
const itL1lbl = newItem(1, 'act');
addLbl(itL1lbl, 'W/2', l1U - 0.28 - 0.95, 0.28, F(17));
addLbl(itL1lbl, 'H/2', l1U - 0.28 + 0.98, 0.28, F(17));

const itBr5 = newItem(1, 'neutral');
addBracket(itBr5, 0.66, 0.33, 2.60);
addLbl(itBr5, rot('5 channels'), 0.47, 1.46, F(14));

/* ---------- ARROWS 2/3 + ELLIPSIS ---------- */
const itArrow2 = newItem(2, 'neutral');
addArrow(itArrow2, 1.05, 2.05, 1.51);
const itDots = newItem(2, 'neutral');
