const itTitleLo = newItem(2, 'neutral');
addStroke(itTitleLo, [[[4.78, 3.04], [5.68, 3.04]]], 0.05);
addLbl(itTitleLo, 'Logits', 5.23, 3.36, F(19));

const itLogits = newItem(2, 'act');
for (let i = 0; i < 9; i++) {
