/* ── item registry (style / stage / family) ───────────────────────────── */
const items = [];
function newItem(stage, fam) {
  const it = { stage, fam: fam || 'neutral', mats: [], divs: [], nodes: [], hiOn: false, lift: 0 };
  items.push(it); return it;
}

/* ── screen-plane ribbon strokes ──────────────────────────────────────── */
function strokeMulti(polys, th, color, depth) {
  const pos = [];
  for (const pts of polys) {
    for (let i = 0; i < pts.length - 1; i++) {
      const x1 = pts[i][0], y1 = pts[i][1], x2 = pts[i + 1][0], y2 = pts[i + 1][1];
      let dx = x2 - x1, dy = y2 - y1; const L = Math.hypot(dx, dy); if (L < 1e-9) continue;
      dx /= L; dy /= L;
      const nx = -dy * th * 0.5, ny = dx * th * 0.5;
      const ex = dx * th * 0.5, ey = dy * th * 0.5;
      const A = W3(x1 - ex + nx, y1 - ey + ny, depth), B = W3(x2 + ex + nx, y2 + ey + ny, depth),
        C = W3(x2 + ex - nx, y2 + ey - ny, depth), D = W3(x1 - ex - nx, y1 - ey - ny, depth);
      pos.push(A.x, A.y, A.z, B.x, B.y, B.z, C.x, C.y, C.z, A.x, A.y, A.z, C.x, C.y, C.z, D.x, D.y, D.z);
    }
