/* ── curves & dashes ──────────────────────────────────────────────────── */
function curvePts(ctrl, n) {
  const v = ctrl.map(p => new THREE.Vector3(p[0], p[1], 0));
  return new THREE.CatmullRomCurve3(v).getPoints(n || 70).map(p => [p.x, p.y]);
