function dashSplit(pts, dash, gap) {
  const out = []; let mode = true, phase = 0, cur = [[pts[0][0], pts[0][1]]];
  let p = [pts[0][0], pts[0][1]];
  for (let k = 1; k < pts.length; k++) {
    const q = pts[k];
    let guard = 0;
    while (guard++ < 500) {
      const dx = q[0] - p[0], dy = q[1] - p[1], L = Math.hypot(dx, dy);
      if (L < 1e-9) break;
      const need = (mode ? dash : gap) - phase;
      if (need > L) { phase += L; p = [q[0], q[1]]; if (mode) cur.push([p[0], p[1]]); break; }
      const t = need / L, np = [p[0] + dx * t, p[1] + dy * t];
      if (mode) { cur.push(np); out.push(cur); cur = null; } else { cur = [np]; }
      mode = !mode; phase = 0; p = np;
    }
  }
  if (mode && cur && cur.length > 1) out.push(cur);
  return out;
}
