function addPlate(it, u, v, S, fill, hiFill, thick) {
  const inset = S >= 1.0 ? 0.09 : (S >= 0.6 ? 0.07 : 0.048);
  const th = thick || (S >= 1.0 ? 0.08 : 0.05);
