  const it = newItem(1, 'filt'); itF1.push(it);
  for (let j = 0; j < 3; j++) {
    const g = addPlate(it, u - 0.05 * j, -1.45 + (1 - j) * 0.38, 0.70, BLUE, BLUEHI);
    if (j === 1) registerInteractive(g, {
      title: 'Layer 1 filter group ' + (k + 1),
      tooltip: 'Filter group ' + (k + 1) + ' — 3×3×3',
      body: 'Three 3×3 kernels stacked, one per RGB input channel. This whole group produces exactly one pink layer-1 feature map.'
    });
  }
}
const itF1lbl = newItem(1, 'filt');
for (let j = 0; j < 3; j++) {
  addLbl(itF1lbl, RGB[j], f1U[0] - 0.05 * j - 0.495 - 0.26, -1.45 + (1 - j) * 0.38, F(16));
}
addLbl(itF1lbl, '3', f1U[0] - 0.10 - 0.44, -2.14, F(16));
addLbl(itF1lbl, '3', f1U[0] - 0.10 + 0.44, -2.14, F(16));

const itCap1 = newItem(1, 'neutral');
addStroke(itCap1, [[[-6.26, -2.36], [-0.80, -2.36]]], 0.05);
addLbl(itCap1, 'layer 1 filters', -3.53, -2.66, F(19));

/* ---------- LAYER 2 FILTERS ---------- */
const itLead2 = newItem(2, 'neutral');
addDashedCurve(itLead2, [[1.80, 1.34], [1.98, 0.96], [2.16, 0.50], [2.25, 0.14]]);

const itBrace2 = newItem(2, 'neutral');
addBrace(itBrace2, 2.25, 1.76, -0.17, 0.30);

const f2U = [1.15, 3.28];
const itF2 = [];
for (let k = 0; k < 2; k++) {
  const it = newItem(2, 'filt'); itF2.push(it);
  for (let j = 0; j < 5; j++) {
    const g = addPlate(it, f2U[k] - 0.05 * j, -1.03 + (2 - j) * 0.38, 0.70, BLUE, BLUEHI);
    if (j === 2) registerInteractive(g, {
      title: 'Layer 2 filter group',
      tooltip: 'Filter group — 3×3×5',
      body: 'A layer-2 filter is five sheets deep because layer 1 handed it five channels: kernel depth always matches the incoming channel count.'
    });
  }
}
const itF2lbl = newItem(2, 'filt');
addLbl(itF2lbl, '<b>• • •</b>', 2.25, -1.05, F(15));
addLbl(itF2lbl, '3', f2U[0] - 0.10 - 0.44, -2.14, F(16));
addLbl(itF2lbl, '3', f2U[0] - 0.10 + 0.44, -2.14, F(16));

const itCap2 = newItem(2, 'neutral');
addStroke(itCap2, [[[0.53, -2.36], [4.08, -2.36]]], 0.05);
addLbl(itCap2, 'layer 2 filters', 2.30, -2.66, F(19));

/* ══════════════════════════════════════════════════════════════════════
   CAMERA — fit by the TRUE drawn extent in screen units.
   The scene's world AABB projects far larger than the flat diagram, so the
   scaffold auto-fit would shrink the figure; compute the zoom directly from
   the (u,v) span instead so the diagram fills the canvas width.
   ══════════════════════════════════════════════════════════════════════ */
const U0 = -9.05, U1 = 8.40, V0 = -2.90, V1 = 3.60;
const SPAN_U = U1 - U0, SPAN_V = V1 - V0;
const TGT = W3((U0 + U1) / 2, (V0 + V1) / 2, 0);
const FRAC = 0.97;
const ISO_ELEV = 35.264389682754654;      // ≡ axisScreenAngles {x:30, z:30}
let tiltDeg = ISO_ELEV;

function applyView() {
  const a = Math.max(0.25, (canvas.clientWidth || 900) / (canvas.clientHeight || 600));
  const z = Math.min(2 * d * a * FRAC / SPAN_U, 2 * d * FRAC / SPAN_V);
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 45,
    elevationDeg: tiltDeg,
    zoom: z,
    target: [TGT.x, TGT.y, TGT.z],
    heightFraction: 0.62
  });
  controls.minPolarAngle = 0.22;
  controls.maxPolarAngle = 1.58;
  controls.minAzimuthAngle = Math.PI / 4 - 0.62;
  controls.maxAzimuthAngle = Math.PI / 4 + 0.62;
  controls.enableRotate = true;
}
applyView();
window.addEventListener('resize', () => setTimeout(applyView, 0));

/* ══════════════════════════════════════════════════════════════════════
   STATE + STYLING
   ══════════════════════════════════════════════════════════════════════ */
const STAGES = ['all', 'input', 'layer1', 'logits', 'argmax'];
const FAMKEY = { activations: 'act', filters: 'filt' };
const state = { stage: 'all', channel: 1, focus: 'both' };

const INFO = {
  all: 'The whole pipeline: pink activation stacks shrink in space while gaining channels, blue filter banks supply the weights, and argmax reads out the class.',
  input: 'Stage 1 — the input tensor: three full-resolution W × H planes (R, G, B).',
  layer1: 'Stage 2 — five filter groups convolve the input into five W/2 × H/2 feature maps.',
  logits: 'Stage 3 — layer-2 filters are 5 sheets deep; after the omitted layers only a 1 × 1 × K logit column remains.',
  argmax: 'Stage 4 — argmax over the K logits picks the winning class: heron.'
};

const DIM_MIX = 0.45, DIM_OPACITY = '0.5';

function setStyles(instant) {
  const si = STAGES.indexOf(state.stage) - 1;   // 'all' → -1 (everything on)
  for (const it of items) {
    const stageOn = state.stage === 'all' ? true : it.stage <= si;
    const famOn = state.focus === 'both' || it.fam === 'neutral' || it.fam === FAMKEY[state.focus];
    const dim = !(stageOn && famOn);
    for (const rec of it.mats) {
      const c = (it.hiOn && rec.hi) ? rec.hi : rec.base;
      const t = c.clone();
      if (dim) t.lerp(WHITE, DIM_MIX);
      rec.target = t;
      if (instant) rec.mat.color.copy(t);
    }
    for (const dv of it.divs) dv.style.opacity = dim ? DIM_OPACITY : '1';
    it.liftTarget = (it.hiOn && !dim) ? 0.35 : 0;
    if (instant) for (const n of it.nodes) n.obj.position.y = n.homeY + it.liftTarget;
  }
}

function applyChannel() {
  for (let k = 0; k < 5; k++) {
    itL1[k].hiOn = (k === state.channel - 1);
    itF1[k].hiOn = (k === state.channel - 1);
  }
}

function refresh(instant) { applyChannel(); setStyles(instant); }

/* tween loop (independent of the scaffold render loop) */
(function figTick() {
  requestAnimationFrame(figTick);
  for (const it of items) {
    for (const rec of it.mats) if (rec.target) rec.mat.color.lerp(rec.target, 0.17);
    const lt = it.liftTarget || 0;
    for (const n of it.nodes) n.obj.position.y += ((n.homeY + lt) - n.obj.position.y) * 0.17;
  }
})();

/* ══════════════════════════════════════════════════════════════════════
   UI WIRING
   ══════════════════════════════════════════════════════════════════════ */
const btnStage = document.getElementById('btnStage');
const stageBtns = Array.from(document.querySelectorAll('.stageBtn'));
const focusBtns = Array.from(document.querySelectorAll('.focusBtn'));
const chSel = document.getElementById('chSel');
const chVal = document.getElementById('chVal');
const tiltSel = document.getElementById('tiltSel');
const tiltVal = document.getElementById('tiltVal');
const narr = document.getElementById('narr');
const demoTitle = document.getElementById('demoTitle');

const btnReset = document.getElementById('btnReset');
btnReset.style.display = '';
btnReset.textContent = '↺ Reset view';
btnReset.addEventListener('click', () => {
  tiltDeg = ISO_ELEV; tiltSel.value = '35'; tiltVal.textContent = '35°';
  applyView();
});

function syncUI() {
  btnStage.textContent = 'Stage: ' + state.stage + '  ▸';
  stageBtns.forEach(b => b.classList.toggle('active', b.dataset.s === state.stage));
  focusBtns.forEach(b => b.classList.toggle('active', b.dataset.f === state.focus));
  chSel.value = String(state.channel);
  chVal.textContent = String(state.channel);
}

btnStage.addEventListener('click', () => {
  state.stage = STAGES[(STAGES.indexOf(state.stage) + 1) % STAGES.length];
  demoTitle.textContent = '';
  narr.textContent = INFO[state.stage];
  syncUI(); refresh(false);
});
stageBtns.forEach(b => b.addEventListener('click', () => {
  state.stage = b.dataset.s;
  demoTitle.textContent = '';
  narr.textContent = INFO[state.stage];
  syncUI(); refresh(false);
}));
focusBtns.forEach(b => b.addEventListener('click', () => {
  state.focus = b.dataset.f;
  demoTitle.textContent = '';
  narr.textContent = state.focus === 'activations'
    ? 'Pink stacks are per-image activations: they shrink spatially while gaining channels.'
    : state.focus === 'filters'
      ? 'Blue stacks are the learned 3×3 weights; their depth must match the incoming channel count.'
      : 'Activations (pink) and filters (blue) shown together.';
  syncUI(); refresh(false);
}));
chSel.addEventListener('input', () => {
  state.channel = parseInt(chSel.value, 10);
  demoTitle.textContent = '';
  narr.textContent = 'Layer-1 output channel ' + state.channel +
    ' is produced by filter group ' + state.channel +
    ' — three 3×3 kernels, one per RGB input channel. Output channels = filter groups.';
  syncUI(); refresh(false);
});
tiltSel.addEventListener('input', () => {
  tiltDeg = parseFloat(tiltSel.value);
  tiltVal.textContent = tiltSel.value + '°';
  applyView();
});

/* ── demo steps ───────────────────────────────────────────────────────── */
const DEMO = [
  { title: 'RGB input', narration: 'The input is three full-resolution pink sheets, W × H × 3, labeled R, G and B; the bracket on the right counts the 3 channels.', state: { stage: 'input', focus: 'activations', channel: 1 } },
  { title: 'Layer 1 convolution', narration: 'Five filter groups, each three 3×3 blue kernels deep, sweep the input and produce five half-size pink feature maps: W/2 × H/2 × 5.', state: { stage: 'layer1', focus: 'both', channel: 3 } },
  { title: 'Deeper layers to logits', narration: 'Layer 2 filters are five sheets deep to match the five incoming channels; after the omitted layers the tensor has collapsed to a 1 × 1 × K column of logits.', state: { stage: 'logits', focus: 'filters', channel: 5 } },
  { title: 'argmax → heron', narration: 'Taking the argmax over the K logits selects the single class label, \u2018heron\u2019.', state: { stage: 'argmax', focus: 'activations', channel: 1 } },
  { title: 'The whole pipeline', narration: 'Read sheet count against sheet size across the diagram: spatial resolution is steadily traded for channel depth as the signal advances.', state: { stage: 'all', focus: 'both', channel: 1 } }
];
let demoIdx = 0, playing = false, playTimer = null;

function goToStep(i) {
  demoIdx = ((i % DEMO.length) + DEMO.length) % DEMO.length;
  const s = DEMO[demoIdx];
  state.stage = s.state.stage; state.focus = s.state.focus; state.channel = s.state.channel;
  demoTitle.textContent = (demoIdx + 1) + '. ' + s.title;
  narr.textContent = s.narration;
  syncUI(); refresh(false);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(demoIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(demoIdx - 1));
const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  playing = !playing;
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play';
  btnPlay.classList.toggle('active', playing);
  if (playing) {
    goToStep(demoIdx);
    playTimer = setInterval(() => goToStep(demoIdx + 1), 4200);
  } else clearInterval(playTimer);
});

/* initial state — full diagram, undimmed, matching the printed figure */
syncUI();
refresh(true);
narr.textContent = INFO.all;
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

