<div id="narr" style="line-height:1.45;color:#333"></div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC (one line per element) ───────────────────────────────────
 // input sheet x3        → BoxGeometry(3,0.08,3) pink #F9D3D2 + black inset box outline
 // layer-1 sheet x5      → BoxGeometry(1.5,0.08,1.5) pink
 // logit diamond x9      → BoxGeometry(0.32,0.05,0.32) pink
 // layer-1 filter 5x3    → BoxGeometry(0.70,0.05,0.70) blue #BFE3F2
 // layer-2 filter 2x5    → BoxGeometry(0.70,0.05,0.70) blue
 // titles/underlines     → screen-plane ribbon Mesh (quads), black
 // channel brackets      → ribbon Mesh vertical line + 2 end caps, black
 // arrows                → ribbon Mesh shaft + flat triangle Mesh head, black
 // curly braces          → CatmullRom sampled ribbon Mesh (two mirrored halves, tall apex)
 // dashed leaders        → CatmullRom sampled, split into dashes, ribbon Mesh
 // all text              → addLabel() HTML (rotated spans for bracket labels)
──────────────────────────────────────────────────────────────────────────── */

/* screen(u,v) → world. Under the canonical isometric pose (azimuth 45°,
   elevation 35.264° ≡ axisScreenAngles {x:30,z:30}) this maps u→screen-x and
   v→screen-y exactly 1:1, and `depth` slides a point straight toward the eye.
   Plates themselves are genuine horizontal XZ slabs; the camera does the
   projecting (nothing is sheared). */
const SX = 0.70710678118, SY = 1.22474487139, DV = 0.57735026919;
function W3(u, v, depth) {
  const dd = (depth || 0) * DV;
  return new THREE.Vector3(u * SX + dd, v * SY + dd, -u * SX + dd);
}

const PINK = 0xF9D3D2, PINKHI = 0xF2A8A3;
const BLUE = 0xBFE3F2, BLUEHI = 0x7FC8E8;
const INK = 0x000000;
const DEPTH = 0.9;                    // annotation layer, toward viewer
const WHITE = new THREE.Color(0xffffff);

/* ── item registry (style / stage / family) ───────────────────────────── */
const items = [];
function newItem(stage, fam) {
  const it = { stage, fam: fam || 'neutral', mats: [], divs: [], nodes: [], hiOn: false, lift: 0 };
  items.push(it); return it;
}

/* ── screen-plane ribbon strokes ──────────────────────────────────────── */
function strokeMulti(polys, th, color, depth) {
  const pos = [];
  for (const pts of polys) {
    for (let i = 0; i < pts.length - 1; i++) {
      const x1 = pts[i][0], y1 = pts[i][1], x2 = pts[i + 1][0], y2 = pts[i + 1][1];
      let dx = x2 - x1, dy = y2 - y1; const L = Math.hypot(dx, dy); if (L < 1e-9) continue;
      dx /= L; dy /= L;
      const nx = -dy * th * 0.5, ny = dx * th * 0.5;
      const ex = dx * th * 0.5, ey = dy * th * 0.5;
      const A = W3(x1 - ex + nx, y1 - ey + ny, depth), B = W3(x2 + ex + nx, y2 + ey + ny, depth),
        C = W3(x2 + ex - nx, y2 + ey - ny, depth), D = W3(x1 - ex - nx, y1 - ey - ny, depth);
      pos.push(A.x, A.y, A.z, B.x, B.y, B.z, C.x, C.y, C.z, A.x, A.y, A.z, C.x, C.y, C.z, D.x, D.y, D.z);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  const m = new THREE.MeshBasicMaterial({ color, side: THREE.DoubleSide });
  const mesh = new THREE.Mesh(g, m); scene.add(mesh);
  return { mesh, mat: m };
}
function addStroke(it, polys, th, color, depth) {
  const r = strokeMulti(polys, th, color === undefined ? INK : color, depth === undefined ? DEPTH : depth);
  it.mats.push({ mat: r.mat, base: new THREE.Color(color === undefined ? INK : color), hi: null });
  return r;
}

/* ── curves & dashes ──────────────────────────────────────────────────── */
function curvePts(ctrl, n) {
  const v = ctrl.map(p => new THREE.Vector3(p[0], p[1], 0));
  return new THREE.CatmullRomCurve3(v).getPoints(n || 70).map(p => [p.x, p.y]);
}
function dashSplit(pts, dash, gap) {
  const out = []; let mode = true, phase = 0, cur = [[pts[0][0], pts[0][1]]];
  let p = [pts[0][0], pts[0][1]];
  for (let k = 1; k < pts.length; k++) {
    const q = pts[k];
    let guard = 0;
    while (guard++ < 500) {
      const dx = q[0] - p[0], dy = q[1] - p[1], L = Math.hypot(dx, dy);
      if (L < 1e-9) break;
      const need = (mode ? dash : gap) - phase;
      if (need > L) { phase += L; p = [q[0], q[1]]; if (mode) cur.push([p[0], p[1]]); break; }
      const t = need / L, np = [p[0] + dx * t, p[1] + dy * t];
      if (mode) { cur.push(np); out.push(cur); cur = null; } else { cur = [np]; }
      mode = !mode; phase = 0; p = np;
    }
  }
  if (mode && cur && cur.length > 1) out.push(cur);
  return out;
}
function addDashedCurve(it, ctrl, th) {
  addStroke(it, dashSplit(curvePts(ctrl, 90), 0.19, 0.13), th || 0.048);
}

/* ── plates (thin box + inset colour box = heavy ink outline) ─────────── */
function addPlate(it, u, v, S, fill, hiFill, thick) {
  const inset = S >= 1.0 ? 0.085 : (S >= 0.6 ? 0.065 : 0.046);
  const th = thick || (S >= 1.0 ? 0.08 : 0.05);
  const g = new THREE.Group();
  const inkMat = new THREE.MeshBasicMaterial({ color: INK });
  g.add(new THREE.Mesh(new THREE.BoxGeometry(S, th, S), inkMat));
  const fillMat = new THREE.MeshBasicMaterial({ color: fill });
  g.add(new THREE.Mesh(new THREE.BoxGeometry(S - inset, th + 0.014, S - inset), fillMat));
  g.position.copy(W3(u, v, 0));
  scene.add(g);
  it.mats.push({ mat: fillMat, base: new THREE.Color(fill), hi: hiFill != null ? new THREE.Color(hiFill) : null });
  it.mats.push({ mat: inkMat, base: new THREE.Color(INK), hi: null });
  it.nodes.push({ obj: g, homeY: g.position.y });
  return g;
}

/* ── arrows ───────────────────────────────────────────────────────────── */
function addArrow(it, u1, u2, v) {
  const head = 0.30, hw = 0.115;
  addStroke(it, [[[u1, v], [u2 - head * 0.85, v]]], 0.055);
  const A = W3(u2, v, DEPTH), B = W3(u2 - head, v + hw, DEPTH), C = W3(u2 - head, v - hw, DEPTH);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(
    [A.x, A.y, A.z, B.x, B.y, B.z, C.x, C.y, C.z], 3));
  const m = new THREE.MeshBasicMaterial({ color: INK, side: THREE.DoubleSide });
  scene.add(new THREE.Mesh(g, m));
  it.mats.push({ mat: m, base: new THREE.Color(INK), hi: null });
}

/* ── vertical channel bracket ─────────────────────────────────────────── */
function addBracket(it, u, v1, v2) {
  const cap = 0.11;
  addStroke(it, [
    [[u, v1], [u, v2]],
    [[u - cap, v1], [u + cap, v1]],
    [[u - cap, v2], [u + cap, v2]]
  ], 0.042);
}

/* ── curly brace, opening downward with a pointed apex on top ─────────── */
/* profile runs end → apex; tight curl at the outer end, second curl just
   before the apex, so it reads as a true brace rather than a flat line.    */
function addBrace(it, uc, halfW, vBase, h) {
  const half = [
    [-1.00, 0.00], [-0.985, 0.26], [-0.94, 0.44],
    [-0.72, 0.53], [-0.36, 0.58], [-0.14, 0.64],
    [-0.055, 0.82], [0, 1.00]
  ];
  const mk = s => curvePts(half.map(([x, y]) => [uc + s * x * halfW, vBase + y * h]), 60);
  addStroke(it, [mk(1), mk(-1)], 0.044);
}

/* ── labels ───────────────────────────────────────────────────────────── */
function addLbl(it, text, u, v, opts) {
  const e = addLabel(text, W3(u, v, 0), opts || {});
  it.divs.push(e.div); return e;
}
const F = s => ({ fontSize: s + 'px' });
const rot = t => '<span style="display:inline-block;transform:rotate(-90deg)">' + t + '</span>';

/* ══════════════════════════════════════════════════════════════════════
   BUILD
   ══════════════════════════════════════════════════════════════════════ */

/* ---------- INPUT ---------- */
const itTitleIn = newItem(0, 'neutral');
addStroke(itTitleIn, [[[-8.00, 3.04], [-4.25, 3.04]]], 0.05);
addLbl(itTitleIn, 'Input', -6.20, 3.36, F(19));

const inU = -6.35, inGap = 0.305;
const inV = [1.83, 1.83 - inGap, 1.83 - 2 * inGap], inDU = [0, -0.06, -0.12];
const itInput = newItem(0, 'act');
const RGB = ['R', 'G', 'B'];
for (let i = 0; i < 3; i++) {
  const g = addPlate(itInput, inU + inDU[i], inV[i], 3.0, PINK, PINKHI);
  registerInteractive(g, {
    title: 'Input channel ' + RGB[i],
    tooltip: 'Input ' + RGB[i] + ' plane — W × H',
    body: 'One of the three W × H colour planes of the input image. Together they form a W × H × 3 tensor.'
  });
  addLbl(itInput, RGB[i], inU + inDU[i] - 2.12 - 0.30, inV[i], F(17));
