/* ══════════════════════════════════════════════════════════════════════
   CAMERA — fit by the TRUE drawn extent in screen units.
   The scene's world AABB projects far larger than the flat diagram, so the
   scaffold auto-fit would shrink the figure; compute the zoom directly from
   the (u,v) span instead so the diagram fills the canvas width.
   ══════════════════════════════════════════════════════════════════════ */
const U0 = -9.15, U1 = 8.45, V0 = -2.95, V1 = 3.60;
const SPAN_U = U1 - U0, SPAN_V = V1 - V0;
const TGT = W3((U0 + U1) / 2, (V0 + V1) / 2, 0);
const FRAC = 0.97;
const ISO_ELEV = 35.264389682754654;      // ≡ axisScreenAngles {x:30, z:30}
let tiltDeg = ISO_ELEV;

function applyView() {
  const a = Math.max(0.25, (canvas.clientWidth || 900) / (canvas.clientHeight || 600));
  const z = Math.min(2 * d * a * FRAC / SPAN_U, 2 * d * FRAC / SPAN_V);
  setCameraView({
    projection: 'orthographic',
    azimuthDeg: 45,
    elevationDeg: tiltDeg,
    zoom: z,
    target: [TGT.x, TGT.y, TGT.z],
    heightFraction: 0.62
  });
  controls.minPolarAngle = 0.22;
  controls.maxPolarAngle = 1.58;
  controls.minAzimuthAngle = Math.PI / 4 - 0.62;
  controls.maxAzimuthAngle = Math.PI / 4 + 0.62;
  controls.enableRotate = true;
}
applyView();
window.addEventListener('resize', () => setTimeout(applyView, 0));

/* ══════════════════════════════════════════════════════════════════════
   STATE + STYLING
   ══════════════════════════════════════════════════════════════════════ */
const STAGES = ['all', 'input', 'layer1', 'logits', 'argmax'];
const FAMKEY = { activations: 'act', filters: 'filt' };
const state = { stage: 'all', channel: 0, focus: 'both' };

const INFO = {
  all: 'The whole pipeline: pink activation stacks shrink in space while gaining channels, blue filter banks supply the weights, and argmax reads out the class.',
  input: 'Stage 1 — the input tensor: three full-resolution W × H planes (R, G, B).',
  layer1: 'Stage 2 — five filter groups convolve the input into five W/2 × H/2 feature maps.',
  logits: 'Stage 3 — layer-2 filters are 5 sheets deep; after the omitted layers only a 1 × 1 × K logit column remains.',
  argmax: 'Stage 4 — argmax over the K logits picks the winning class: heron.'
};

const DIM_MIX = 0.45, DIM_OPACITY = '0.5';

function setStyles(instant) {
  const si = STAGES.indexOf(state.stage) - 1;   // 'all' → -1 (everything on)
  for (const it of items) {
    const stageOn = state.stage === 'all' ? true : it.stage <= si;
    const famOn = state.focus === 'both' || it.fam === 'neutral' || it.fam === FAMKEY[state.focus];
    const dim = !(stageOn && famOn);
    for (const rec of it.mats) {
      const c = (it.hiOn && rec.hi) ? rec.hi : rec.base;
      const t = c.clone();
      if (dim) t.lerp(WHITE, DIM_MIX);
      rec.target = t;
      if (instant) rec.mat.color.copy(t);
    }
    for (const dv of it.divs) dv.style.opacity = dim ? DIM_OPACITY : '1';
    it.liftTarget = (it.hiOn && !dim) ? 0.35 : 0;
    if (instant) for (const n of it.nodes) n.obj.position.y = n.homeY + it.liftTarget;
  }
}

function applyChannel() {
  for (let k = 0; k < 5; k++) {
    const on = state.channel > 0 && k === state.channel - 1;
    itL1[k].hiOn = on;
    itF1[k].hiOn = on;
  }
}

function refresh(instant) { applyChannel(); setStyles(instant); }

/* tween loop (independent of the scaffold render loop) */
(function figTick() {
  requestAnimationFrame(figTick);
  for (const it of items) {
    for (const rec of it.mats) if (rec.target) rec.mat.color.lerp(rec.target, 0.17);
    const lt = it.liftTarget || 0;
    for (const n of it.nodes) n.obj.position.y += ((n.homeY + lt) - n.obj.position.y) * 0.17;
  }
})();

