/* ── demo steps ───────────────────────────────────────────────────────── */
const DEMO = [
  { title: 'RGB input', narration: 'The input is three full-resolution pink sheets, W × H × 3, labeled R, G and B; the bracket on the right counts the 3 channels.', state: { stage: 'input', focus: 'activations', channel: 0 } },
  { title: 'Layer 1 convolution', narration: 'Five filter groups, each three 3×3 blue kernels deep, sweep the input and produce five half-size pink feature maps: W/2 × H/2 × 5.', state: { stage: 'layer1', focus: 'both', channel: 3 } },
  { title: 'Deeper layers to logits', narration: 'Layer 2 filters are five sheets deep to match the five incoming channels; after the omitted layers the tensor has collapsed to a 1 × 1 × K column of logits.', state: { stage: 'logits', focus: 'filters', channel: 5 } },
  { title: 'argmax → heron', narration: 'Taking the argmax over the K logits selects the single class label, \u2018heron\u2019.', state: { stage: 'argmax', focus: 'activations', channel: 0 } },
  { title: 'The whole pipeline', narration: 'Read sheet count against sheet size across the diagram: spatial resolution is steadily traded for channel depth as the signal advances.', state: { stage: 'all', focus: 'both', channel: 0 } }
];
let demoIdx = 0, playing = false, playTimer = null;

function goToStep(i) {
  demoIdx = ((i % DEMO.length) + DEMO.length) % DEMO.length;
  const s = DEMO[demoIdx];
  state.stage = s.state.stage; state.focus = s.state.focus; state.channel = s.state.channel;
  demoTitle.textContent = (demoIdx + 1) + '. ' + s.title;
  narr.textContent = s.narration;
  syncUI(); refresh(false);
}
document.getElementById('btnNext').addEventListener('click', () => goToStep(demoIdx + 1));
document.getElementById('btnPrev').addEventListener('click', () => goToStep(demoIdx - 1));
const btnPlay = document.getElementById('btnPlay');
btnPlay.addEventListener('click', () => {
  playing = !playing;
  btnPlay.textContent = playing ? '❚❚ Pause' : '▶ Play';
  btnPlay.classList.toggle('active', playing);
  if (playing) {
    goToStep(demoIdx);
    playTimer = setInterval(() => goToStep(demoIdx + 1), 4200);
  } else clearInterval(playTimer);
});

/* initial state — full diagram, undimmed, no highlight: matches the print */
syncUI();
refresh(true);
narr.textContent = INFO.all;
